function actor(ctx:SessionContext,c:Context):CurrentUserActor{const u=c.users.find(u=>u.id===ctx.userId);if(!u||!ctx.userId)forbidden('Sign in with an active assigned account.');if((ctx.personId??null)!==(u.personId??null))forbidden('Your account identity changed. Sign in again before acting.');return{userId:ctx.userId,personId:u.personId??null,name:u.name,at:when(),today:todayInKualaLumpur()};}
function linkedLetterActor(by:CurrentUserActor):ResignationLetterActor{if(!by.personId)forbidden('A linked person is required to act on a signing document.');return{...by,personId:by.personId};}
