function available(c:Context,members:readonly string[],groupId:string|null=null):string[]{const group=c.config?.groups.find(g=>g.id===groupId);return [...new Set(members)].filter(id=>c.users.some(u=>u.id===id)&&!(c.unavailableUserIds??[]).includes(id)&&(!group?.limit||Number(c.assignmentLoads?.find(x=>x.userId===id)?.taskLoad??0)<group.limit));}
function effectiveRouting(c:Context,id:string):Routing|null{const rt=c.routings.find(r=>r.id===id);if(!rt)return null;const match=resolveRoutingRow(rt,{businessGroup:c.businessGroupId,company:c.companyId,department:c.departmentId,jobTitle:c.positionId??null});const candidates=(row:Routing['rows'][number])=>row.assignTo.kind==='people'?available(c,row.assignTo.userIds):available(c,c.config?.groups.find(g=>row.assignTo.kind==='group'&&g.id===row.assignTo.groupId)?.members??[],row.assignTo.groupId);if(match&&candidates(match.row).length)return rt;const fallback=rt.rows.find(row=>Object.values(row.match).every(v=>!v?.length));return fallback&&candidates(fallback).length?{...rt,rows:[fallback]}:null;}
function choose(c:Context,members:readonly string[],rule:'any'|'roundRobin',groupId:string|null=null):string|null{const candidates=available(c,members,groupId);if(rule==='roundRobin')candidates.sort((a,b)=>Number(c.assignmentLoads?.find(x=>x.userId===a)?.taskLoad??0)-Number(c.assignmentLoads?.find(x=>x.userId===b)?.taskLoad??0)||String(c.assignmentLoads?.find(x=>x.userId===a)?.lastAuto??'').localeCompare(String(c.assignmentLoads?.find(x=>x.userId===b)?.lastAuto??''))||members.indexOf(a)-members.indexOf(b));return candidates[0]??null;}
function resolve(c:Context,list:readonly AutomationRecipient[],pending:string[]=[]):string[]{const out:string[]=[];for(const x of list){let found:string[]=[];if(x.kind==='role')found=x.role==='employee'?[c.employeeUserId??'']:x.role==='directSuperior'?[c.supervisorUserId??'']:[];else if(x.kind==='person')found=available(c,[x.userId]);else if(x.kind==='group')found=available(c,c.config?.groups.find(g=>g.id===x.groupId)?.members??[],x.groupId);else if(x.kind==='pending')found=pending;else{const rt=effectiveRouting(c,x.routingId);if(rt){const row=resolveRoutingRow(rt,{businessGroup:c.businessGroupId,company:c.companyId,department:c.departmentId,jobTitle:c.positionId??null})?.row;if(row)found=row.assignTo.kind==='people'?available(c,row.assignTo.userIds):available(c,c.config?.groups.find(g=>row.assignTo.kind==='group'&&g.id===row.assignTo.groupId)?.members??[],row.assignTo.groupId);}}found=found.filter(id=>c.users.some(u=>u.id===id));if(!found.length)invalid('Nobody was found for a configured recipient. Check Assignment groups and Routing rules.');out.push(...found);}return[...new Set(out)];}

function roleRecipients(roles:readonly Role[]):AutomationRecipient[]{return roles.map(role=>role.startsWith('group:')?{kind:'group',groupId:role.slice(6)}:role.startsWith('person:')?{kind:'person',userId:role.slice(7)}:{kind:'role',role:role==='supervisor'?'directSuperior':role==='employeeWork'||role==='employeePersonal'?'employee':role});}
