async function flagMissingDecision(tx:Tx,ctx:SessionContext,r:Row,c:Context,trigger:'submitted'|'rejected'|'offerDeclined'){const reason='Nobody was asked to record the resignation decision. HR must repair the configuration and run workflows again.';r.data.blocked=[...new Set([...r.data.blocked,reason])];const[audience]=await tx.execute<{people:(ResignationPerson&{personId:string|null})[]}>(sql`select app.resignation_decision_repair_audience(${r.id}::uuid) as people`);const people=audience?.people??[];for(const person of people)if(!c.users.some(user=>user.id===person.id))c.users.push(person);const repair={id:randomUUID(),to:people.map(person=>person.id),createdOn:todayInKualaLumpur(),trigger};r.data.decisionRepair=repair;if(!repair.to.length)r.data.blocked.push('No active PeopleOps or authorized Offboarding HR recipient is configured. No repair notification was sent.');await save(tx,ctx,r,c);if(repair.to.length)await notify(tx,ctx,r,`${repair.id}:decision-unassigned`,repair.to,[],'Resignation decision needs configuration',`${c.employeeName} submitted a resignation. ${reason}`);await appendEvent(tx,{tenantId:ctx.tenantId,aggregateType:'resignation-journey',aggregateId:r.id,eventType:'resignation.decision.unassigned',actor:actorOf(ctx),subjectEmploymentId:r.employment_id,payload:{repairTaskId:repair.id,recipientCount:repair.to.length,notificationQueued:repair.to.length>0}});}
async function fire(tx:Tx,ctx:SessionContext,r:Row,c:Context,trigger:string,event:EventContext={},depth=0){if(depth>20)invalid('The workflow event chain is too deep. Review its configuration.');r.data.eventSerial++;await save(tx,ctx,r,c);const result=await runAutomationEventTx(tx,{module:'off',event:{trigger,subjectId:r.id,occurrence:`${r.data.eventSerial}`,today:todayInKualaLumpur(),read:readFacts(r,c,event.letter),anchor:()=>null,skipReason:skip=>skip==='caseClosed'&&CLOSED.has(r.stage)?'the case is closed':null},executors:await executors(tx,ctx,r,c,event,depth)});if((trigger==='submitted'||trigger==='rejected'||trigger==='offerDeclined')&&!r.data.decision)await flagMissingDecision(tx,ctx,r,c,trigger);if(trigger==='accepted'&&!result.matched)r.stage='leaving';if(trigger==='retention'&&!result.matched)r.data.blocked.push('No Live workflow handles the retention offer. Configure one and run workflows again.');await save(tx,ctx,r,c);}
